-- Synthetic lifecycle fixtures; no provider calls. All changes roll back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not has_table_privilege('authenticated','public.application_packages','UPDATE'),'package snapshots cannot be rewritten');
select ok(not has_table_privilege('authenticated','public.application_packages','DELETE'),'package history cannot be individually erased');
select ok(not has_table_privilege('anon','public.resume_facts','SELECT'),'resume text is private');
select ok(not has_function_privilege('anon','public.record_application_package(uuid,uuid,uuid,timestamptz,timestamptz,timestamptz,timestamptz,jsonb,jsonb)','EXECUTE'),'anonymous package generation denied');
insert into auth.users(id,email) values('16000000-0000-0000-0000-000000000001','prep-one@example.test'),('16000000-0000-0000-0000-000000000002','prep-two@example.test');
insert into public.candidate_profiles(id,user_id,full_name,email) values('26000000-0000-0000-0000-000000000001','16000000-0000-0000-0000-000000000001','Preparation Fixture','prep-one@example.test');
insert into public.resumes(id,user_id,profile_id,role_category,version_name,storage_path) values('36000000-0000-0000-0000-000000000001','16000000-0000-0000-0000-000000000001','26000000-0000-0000-0000-000000000001','backend','Synthetic v1','16000000-0000-0000-0000-000000000001/prep.txt');
insert into public.jobs(id,user_id,source_platform,canonical_url,company_name,job_title,description) values('46000000-0000-0000-0000-000000000001','16000000-0000-0000-0000-000000000001','manual','https://example.test/prep','Synthetic employer','Backend','Fully remote contract worldwide Pakistan USD monthly mid backend USA authorization Python');
insert into public.applications(id,user_id,job_id) values('56000000-0000-0000-0000-000000000001','16000000-0000-0000-0000-000000000001','46000000-0000-0000-0000-000000000001');
set local role authenticated;
set local request.jwt.claim.sub='16000000-0000-0000-0000-000000000001';
insert into public.resume_facts(resume_id,user_id,text_content) values('36000000-0000-0000-0000-000000000001',auth.uid(),'Synthetic factual resume text.');

update public.resume_facts set verified_by_candidate=true;
update public.jobs set listing_status='active';
create temporary table context as select j.id,j.updated_at job_time,p.updated_at profile_time from public.jobs j cross join public.candidate_profiles p where j.id='46000000-0000-0000-0000-000000000001';
create temporary table source_review as select '{"citations":[{"kind":"remote","quote":"Fully remote","url":"https://example.test/prep"},{"kind":"country","quote":"worldwide Pakistan","url":"https://example.test/prep"},{"kind":"salary","quote":"USD monthly","url":"https://example.test/prep"},{"kind":"role","quote":"backend","url":"https://example.test/prep"},{"kind":"employment","quote":"contract","url":"https://example.test/prep"},{"kind":"seniority","quote":"mid","url":"https://example.test/prep"},{"kind":"region","quote":"USA","url":"https://example.test/prep"},{"kind":"authorization","quote":"authorization","url":"https://example.test/prep"}],"source_checked":true,"listing_checked":true,"qualifications":"met","authorization":"met"}'::jsonb review;
create temporary table screen_result as select '{"decision":"ELIGIBLE","remote_check":"pass","pakistan_eligibility":"pass","salary_check":"pass","match_score":100,"confidence":1,"reasons":["Synthetic database fixture only"],"evidence_urls":["https://example.test/prep"],"factors":{"monthly_min":2000,"currency":"USD"},"evaluation_version":"phase3.1"}'::jsonb result;
select lives_ok($$select public.record_job_screening(id,job_time,profile_time,'[]',(select review from source_review),(select result from screen_result)) from context$$,'screening and review snapshot saved transactionally');

select public.record_application_package((select id from public.applications),(select id from public.resumes),gen_random_uuid(),(select updated_at from public.applications),(select updated_at from public.jobs),(select updated_at from public.candidate_profiles),(select updated_at from public.resume_facts),'[]','{"answers":[],"cover_letter":"Synthetic letter"}');
select public.review_application_package((select id from public.application_packages),(select updated_at from public.applications));
create function pg_temp.record_run(mode text,request uuid default gen_random_uuid()) returns uuid language sql as $$
 select public.record_submission_run((select id from public.applications),(select id from public.application_packages),request,mode,public.submission_snapshot((select id from public.applications),(select id from public.application_packages)),'{"version":"phase5.1","ready":true,"checks":[]}');
$$;
select is((select status from public.applications),'prepared','fixture package is reviewed and eligible');
select ok(not has_table_privilege('anon','public.submission_runs','SELECT'),'anonymous handoff history denied');
select ok(not has_table_privilege('authenticated','public.submission_runs','INSERT'),'direct insertion cannot forge attempt states');
select ok(not has_table_privilege('authenticated','public.submission_runs','UPDATE'),'direct history rewriting denied');
select ok(not has_table_privilege('authenticated','public.submission_runs','DELETE'),'direct duplicate guard deletion denied');
select ok(not has_function_privilege('authenticated','public.reconcile_handoff_report()','EXECUTE'),'reconciliation privilege restricted to trigger');
select ok(not has_function_privilege('anon','public.finish_submission_handoff(uuid,text,text,timestamptz)','EXECUTE'),'anonymous confirmation denied');
select lives_ok($$select pg_temp.record_run('dry_run','66000000-0000-0000-0000-000000000001')$$,'dry check allowed while handoffs are paused');
select lives_ok($$select pg_temp.record_run('dry_run','66000000-0000-0000-0000-000000000001')$$,'same request id resolves without duplicate');
select is((select count(*) from public.submission_runs),1::bigint,'one immutable dry run after retry');
select is((select count(*) from public.application_events where event_type='submission_checked'),1::bigint,'one audit event after retry');
select is((select applied_at from public.applications),null::timestamptz,'dry run never changes actual submissions');
select throws_ok($$select pg_temp.record_run('authorized_api')$$,'22023',null,'unconfigured API route cannot be invoked through RPC');
select throws_ok($$select pg_temp.record_run('human_assisted','66000000-0000-0000-0000-000000000001')$$,'23505',null,'request cannot be reinterpreted as a different mode');
select throws_ok($$select pg_temp.record_run('human_assisted')$$,'23514',null,'manual handoffs start globally paused');
insert into public.submission_controls(user_id,scope,paused) values(auth.uid(),'global',false),(auth.uid(),'source:manual',true);
select throws_ok($$select pg_temp.record_run('human_assisted')$$,'23514',null,'source switch blocks even when global enabled');
update public.submission_controls set paused=false where scope='source:manual';
select throws_ok($$select public.record_submission_run((select id from public.applications),(select id from public.application_packages),gen_random_uuid(),'dry_run','{}','{"version":"phase5.1","ready":true,"checks":[]}')$$,'40001',null,'stale input fingerprint cannot be recorded');
select lives_ok($$select pg_temp.record_run('human_assisted')$$,'enabled current reviewed package creates handoff');
select lives_ok($$select pg_temp.record_run('human_assisted')$$,'different request cannot open a second handoff');
select is((select count(*) from public.submission_runs where mode='human_assisted'),1::bigint,'one active handoff per application');
select is((select applied_at from public.applications),null::timestamptz,'handoff is not a completed submission');
select throws_ok($$select public.finish_submission_handoff((select id from public.submission_runs where mode='human_assisted'),'candidate_reported','Synthetic actual receipt',clock_timestamp()+interval '1 day')$$,'23514',null,'future receipt time denied');
select throws_ok($$select public.finish_submission_handoff((select id from public.submission_runs where mode='human_assisted'),'verified','Synthetic API receipt')$$,'23514',null,'candidate cannot claim provider verification');
select lives_ok($$select public.finish_submission_handoff((select id from public.submission_runs where mode='human_assisted'),'uncertain','Synthetic timeout; receipt not yet checked')$$,'uncertainty recorded without claiming success');
select is((select applied_at from public.applications),null::timestamptz,'uncertainty does not change daily actual submissions');
select lives_ok($$select pg_temp.record_run('human_assisted')$$,'retry resolves existing uncertain record');
select is((select count(*) from public.submission_runs where mode='human_assisted'),1::bigint,'uncertain handoff retains duplicate claim');
update public.submission_controls set paused=true where scope='global';
select lives_ok($$select public.finish_submission_handoff((select id from public.submission_runs where mode='human_assisted'),'cancelled','Candidate checked; no application was submitted')$$,'actual outcome can be recorded while paused');
update public.submission_controls set paused=false where scope='global';
select lives_ok($$select pg_temp.record_run('human_assisted')$$,'explicit no-submission cancellation allows a new handoff');
select lives_ok($$select public.finish_submission_handoff((select id from public.submission_runs where state='handoff_ready'),'candidate_reported','Synthetic receipt after completing official form',clock_timestamp())$$,'actual manual receipt saved atomically');
select is((select status from public.applications),'submitted','reported completion updates application status');
select is((select confirmation_evidence->>'kind' from public.applications),'candidate_reported','manual receipt never labeled API verified');
select is((select count(*) from public.submission_runs where state='candidate_reported'),1::bigint,'receipt reconciles active handoff');
select throws_ok($$delete from public.applications$$,'23503',null,'retained history prevents deleting duplicate protection');
set local request.jwt.claim.sub='16000000-0000-0000-0000-000000000002';
select is((select count(*) from public.submission_runs),0::bigint,'other owner cannot read attempts');
select is((select count(*) from public.submission_controls),0::bigint,'other owner cannot read pause settings');
select is(public.submission_snapshot('56000000-0000-0000-0000-000000000001',gen_random_uuid()),null::jsonb,'foreign snapshots inaccessible');
select throws_ok($$select public.record_submission_run('56000000-0000-0000-0000-000000000001',gen_random_uuid(),gen_random_uuid(),'dry_run','{}','{}')$$,'42501',null,'foreign app cannot receive attempt');
select throws_ok($$insert into public.submission_controls(user_id,scope,paused) values('16000000-0000-0000-0000-000000000001','source:other',false)$$,'42501',null,'foreign pause setting denied');
reset role;
select lives_ok($$delete from auth.users where id='16000000-0000-0000-0000-000000000001'$$,'account deletion removes private handoff history through Auth cascade');
select is((select count(*) from public.submission_runs where user_id='16000000-0000-0000-0000-000000000001'),0::bigint,'no private history retained after account deletion');
select * from finish();
rollback;
